scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 420) @Event420;
	If ($Event == 440) @Event440;
	If ($Event == 530) @Event530;
	If ($Event >= 695) @Event695;
	
	Return;
	
@Event420:	
	Say("张琳心：我们赶快去宋军大营吧。", 21);
	Return;
	
@Event440:
	Say("张琳心：独孤哥哥，我们现在就去军营吧。", 21);
	Return;		
	
@Event530:
	Say("张琳心：王将军在码头等着我们呢，不知有什么事。", 21);
	Return;		
		
@Event695:
	Say("张琳心：独孤哥哥，我们快去岳飞大营。",21);
	Return;

